#!/usr/bin/env python3
"""Generate literal hardware-oracle instructions from the compact unary cases."""
from pathlib import Path
import argparse
import json

ROOT = Path(__file__).resolve().parents[1]


def generate():
    spec = json.loads((ROOT/'tests/sdk/linux-host/sparse-unary-cases.json').read_text())
    lines = ['''// SPDX-License-Identifier: GPL-3.0-or-later
// Generated by scripts/generate-sparse-unary-tests.py; hardware supplies results.
// Host flags are restored after every literal unary instruction.
#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#define EXEC(bytes) __asm__ volatile("pushfq; pop %[original]; push %[seed]; popfq; " bytes "; pushfq; pop %[flags]; push %[original]; popfq" : [original] "=&r"(original), [flags] "=&r"(flags), "+a"(value) : [seed] "r"(seed) : "cc","memory")
int main(void) {
 uint64_t current;__asm__ volatile("pushfq; pop %0":"=r"(current)::"memory");
 const unsigned widths[]={'''+','.join(str(f['width']) for f in spec['forms'])+'''},shifts[]={'''+','.join(str(f['shift']) for f in spec['forms'])+'''},seeds[]={'''+','.join(str(n) for n in spec['flagSeeds'])+'''};
 int comma=0;puts("[");
 for(unsigned form=0;form<@CASE_COUNT@;form++)for(unsigned si=0;si<@SEED_COUNT@;si++)for(unsigned input=0;input<@INPUT_COUNT@;input++) {
  const unsigned width=widths[form%@FORM_COUNT@],shift=shifts[form%@FORM_COUNT@],bits=width*8;
  const uint64_t mask=width==8?UINT64_MAX:(UINT64_C(1)<<bits)-1,sign=UINT64_C(1)<<(bits-1),values[]={0,1,2,15,16,17,0x7f,0x80,0xff,sign-1,sign,sign+1,mask-1,mask,mask^0x55,mask>>1};
  uint64_t value=(UINT64_C('''+spec['unrelatedBits']+''')&~(mask<<shift))|((values[input]&mask)<<shift),original,flags;
  const uint64_t seed=(current&~UINT64_C(0xcd5))|seeds[si];
  switch(form){''']
    i = 0
    by_kind = {op['kind']: op for op in spec['operations']}
    sequences = [[op['kind']] for op in spec['operations']] + spec['sequences']
    for sequence in sequences:
        for form in spec['forms']:
            width, shift = form['width'], form['shift']
            bodies = []
            for kind in sequence:
                op = by_kind[kind]
                code = ([0x66] if width == 2 else [0x48] if width == 8 else [])
                code += [op['byteOpcode'] if width == 1 else op['wideOpcode'], 0xc0 | op['group'] << 3 | (4 if shift else 0)]
                bodies.append('.byte ' + ','.join(hex(b) for b in code))
            lines.append(f'   case {i}:EXEC("' + '; '.join(bodies) + '");break;')
            i += 1
    lines.append('''   default:return 2;
  }
  printf("%s[%u,%u,%u,\\"0x%" PRIx64 "\\",%u]",comma?",\\n":"",form,si,input,value,(unsigned)flags&0xcd5);comma=1;
 }
 puts("\\n]");return 0;
}
''')
    return '\n'.join(lines).replace('@CASE_COUNT@', str(i)).replace('@SEED_COUNT@', str(len(spec['flagSeeds']))).replace('@INPUT_COUNT@', str(spec['inputCount'])).replace('@FORM_COUNT@', str(len(spec['forms'])))


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--check', action='store_true')
    args = p.parse_args()
    dest = ROOT/'tests/sdk/linux-host/sparse-unary-oracle.c'
    text = generate()
    if args.check:
        if dest.read_text() != text:
            raise SystemExit('Generated unary oracle source differs')
        print('Unary literal oracle source matches the compact description')
    else:
        dest.write_text(text)


if __name__ == '__main__':
    main()
